    public void load(ResultSet rs, int id) throws SQLException {
        this.id = id;
        java.sql.Date date;
        date = rs.getDate(2);
        if (date != null) this.dateCreated = new OADate(date);
        this.type = rs.getInt(3);
        OAObjectInfoDelegate.setPrimitiveNull(this, P_Type, rs.wasNull());
        this.statusCode = rs.getInt(4);
        date = rs.getDate(5);
        if (date != null) this.scheduledEndDate = new OADate(date);
        date = rs.getDate(6);
        if (date != null) this.inspectByDate = new OADate(date);
        date = rs.getDate(7);
        if (date != null) this.inspectDate = new OADate(date);
        date = rs.getDate(8);
        if (date != null) this.completeDate = new OADate(date);
        int inspectUserFkey = rs.getInt(9);
        setFkeyProperty(P_InspectUser, rs.wasNull() ? null : inspectUserFkey);
        int orderFkey = rs.getInt(10);
        setFkeyProperty(P_Order, rs.wasNull() ? null : orderFkey);

        this.changedFlag = false;
        this.newFlag = false;
    }
